import { MakeLogicType, afterMount, kea, path } from 'kea'
import { loaders } from 'kea-loaders'

import { ApiConfig } from 'lib/api'

import { linksList } from './generated/api'
import type { LinkApi } from './generated/api.schemas'

type LinkType = LinkApi

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface linksLogicValues {
    links: LinkType[]
    linksLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface linksLogicActions {
    loadLinks: () => any
    loadLinksFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadLinksSuccess: (
        links: LinkApi[],
        payload?: any
    ) => {
        links: LinkApi[]
        payload?: any
    }
}

export type linksLogicType = MakeLogicType<linksLogicValues, linksLogicActions>

export const linksLogic = kea<linksLogicType>([
    path(() => ['scenes', 'links', 'linksLogic']),
    loaders(() => ({
        links: [
            [] as LinkType[],
            {
                loadLinks: async () => {
                    const response = await linksList(String(ApiConfig.getCurrentProjectId()), { limit: 100 })
                    return response.results
                },
            },
        ],
    })),

    afterMount(({ actions }) => {
        actions.loadLinks()
    }),
])
